const input = $json;
let candidate = input;
if (typeof input.chatInput === 'string' && !input.payload) {
  try {
    candidate = JSON.parse(input.chatInput);
  } catch (e) {
    candidate = input;
  }
}
const requiredTop = ['status_kind', 'result_type', 'payload'];
const requiredPayload = ['tenant_id', 'thread_id', 'execution_id', 'trigger_message_id', 'idempotency_key', 'status', 'ttl_seconds'];
const missing = [];
if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) {
  return [{ json: {
    _valid: 'false',
    error_code: 'INVALID_HANDOFF_INPUT',
    error_message: 'Input is not a JSON object.',
    missing_fields: ['root']
  }}];
}
for (const key of requiredTop) {
  if (!(key in candidate)) missing.push(key);
}
const payload = candidate.payload && typeof candidate.payload === 'object' ? candidate.payload : {};
for (const key of requiredPayload) {
  if (!(key in payload)) missing.push(`payload.${key}`);
}
if (missing.length) {
  return [{ json: {
    _valid: 'false',
    error_code: 'INVALID_HANDOFF_INPUT',
    error_message: 'Required handoff fields are missing.',
    missing_fields: [...new Set(missing)].sort()
  }}];
}
if (candidate.status_kind !== 'success') {
  return [{ json: {
    _valid: 'false',
    error_code: 'INVALID_HANDOFF_INPUT',
    error_message: 'status_kind must be success.',
    missing_fields: ['status_kind']
  }}];
}
if (candidate.result_type !== 'state') {
  return [{ json: {
    _valid: 'false',
    error_code: 'INVALID_HANDOFF_INPUT',
    error_message: 'result_type must be state.',
    missing_fields: ['result_type']
  }}];
}
if (String(payload.status) !== 'initialized') {
  return [{ json: {
    _valid: 'false',
    error_code: 'NOT_READY_FOR_PLANNING',
    error_message: 'Execution context is not initialized.',
    missing_fields: ['payload.status']
  }}];
}
return [{ json: {
  _valid: 'true',
  _normalized_ec_result: {
    status_kind: 'success',
    result_type: 'state',
    module_name: candidate.module_name || 'execution_context_init',
    warnings: Array.isArray(candidate.warnings) ? candidate.warnings : [],
    payload: {
      tenant_id: String(payload.tenant_id),
      thread_id: String(payload.thread_id),
      execution_id: String(payload.execution_id),
      trigger_message_id: String(payload.trigger_message_id),
      idempotency_key: String(payload.idempotency_key),
      status: String(payload.status),
      ttl_seconds: Number(payload.ttl_seconds)
    }
  }
}}];

const ec = $json._normalized_ec_result;
const p = ec.payload;
return [{ json: {
  tenant_id: p.tenant_id,
  thread_id: p.thread_id,
  execution_id: p.execution_id,
  trigger_message_id: p.trigger_message_id,
  idempotency_key: p.idempotency_key,
  expected_status: p.status,
  ttl_seconds: p.ttl_seconds,
  source_module: ec.module_name,
  warnings: ec.warnings || []
}}];

const row = $json;
const handoff = {
  execution_id: String(row.execution_id || ''),
  tenant_id: String(row.tenant_id || ''),
  thread_id: String(row.thread_id || ''),
  trigger_message_id: String(row.trigger_message_id || ''),
  expected_status: String(row.status || '')
};
if (!handoff.execution_id || !handoff.tenant_id || !handoff.thread_id || !handoff.trigger_message_id) {
  return [{ json: {
    _valid: 'false',
    error_code: 'CONTEXT_MISMATCH',
    error_message: 'Execution context row was not found or is incomplete.',
    missing_fields: ['execution_context']
  }}];
}
return [{ json: {
  _valid: 'true',
  execution_id: handoff.execution_id,
  tenant_id: handoff.tenant_id,
  thread_id: handoff.thread_id,
  trigger_message_id: handoff.trigger_message_id,
  idempotency_key: String(row.idempotency_key || ''),
  expected_status: handoff.expected_status,
  ttl_seconds: row.ttl_seconds,
  warnings: []
}}];

return [{ json: {
  status_kind: 'success',
  result_type: 'handoff',
  module_name: 'orchestrator_input_handoff',
  payload: {
    tenant_id: String($json.tenant_id),
    thread_id: String($json.thread_id),
    execution_id: String($json.execution_id),
    trigger_message_id: String($json.trigger_message_id),
    idempotency_key: String($json.idempotency_key),
    execution_status: String($json.expected_status),
    planning_allowed: true,
    allowed_next_stage: 'WF-PL-01',
    orchestrator_input: {
      planning_mode: 'plan_only',
      module_execution_allowed: false,
      response_generation_allowed: false,
      domain_writes_allowed: false
    },
    warnings: Array.isArray($json.warnings) ? $json.warnings : []
  }
}}];

return [{ json: {
  status_kind: 'failed',
  result_type: 'error',
  module_name: 'orchestrator_input_handoff',
  error: {
    code: $json.error_code || 'INVALID_HANDOFF_INPUT',
    message: $json.error_message || 'Unknown handoff error.',
    missing_fields: Array.isArray($json.missing_fields) ? $json.missing_fields : []
  }
}}];
